package main

const federationPageStyle = `<style>
body{max-width:1080px}.topline{margin-bottom:26px}.topline h1{font-size:clamp(30px,4vw,42px)}section{box-shadow:0 10px 26px rgba(0,34,37,.06)}section h2{margin-bottom:10px}.federation-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:20px}.federation-form label{display:flex;flex-direction:column;gap:5px;font-size:12px;font-weight:700}.federation-form input{width:100%;margin:0;min-height:42px;border-color:var(--line);background:var(--bg)}.federation-form button{grid-column:1/-1;justify-self:start;margin:0}.trust-record,.conflict-record{padding:16px 0;border-top:1px solid var(--line)}.trust-record h3,.conflict-record h3{margin:0 0 8px}.trust-record code,.conflict-record code{overflow-wrap:anywhere}.trust-record form,.conflict-record form{margin:12px 0 0}.conflict-record dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:14px 0}.conflict-record dt{color:var(--muted);font-size:12px}.conflict-record dd{margin:3px 0 0}.conflict-approved{color:#2b806f;font-weight:700}html[data-theme="light"] .federation-form input{background:#fff}@media(max-width:620px){.federation-form,.conflict-record dl{grid-template-columns:1fr}}
</style>`
